const VALID_SLOT_KEYS=new Set(CARD_IDS.flatMap(id=>ROLES.map(role=>`${id}:${role}`)));
let progress={};try{const p=JSON.parse(localStorage.getItem('colors1000_verified_progress')||'{}');if(p&&typeof p==='object')progress=p;}catch{}
const research=c=>RESEARCH_DATA[c.name]||{};
function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,5500);}
function safeLink(value){try{const u=new URL(String(value));return ['https:','http:'].includes(u.protocol)?u.href:'';}catch{return '';}}
function safeImage(value){const v=String(value||'');if(/^assets\/[a-f0-9]{64}\.(?:jpg|jpeg|png|webp|gif)$/i.test(v))return v;if(/^data:image\/(?:png|jpeg|webp|gif);base64,[a-z0-9+/=\r\n]+$/i.test(v))return v;return safeLink(v);}
/* 外部URLはカードとは別のポップアップ型ウィンドウで開く。ブラウザが許可しない場合は理由を表示。 */
function externalLink(url,label){const href=safeLink(url);return href?`<a href="${escapeHtml(href)}" target="_blank" rel="noopener noreferrer" data-color-external-window="1">${escapeHtml(label)}</a>`:'';}
document.addEventListener('click',function(event){
  if(event.defaultPrevented || event.button!==0 || event.ctrlKey || event.metaKey || event.altKey || event.shiftKey)return;
  const anchor=event.target&&event.target.closest?event.target.closest('a[href]'):null;
  if(!anchor)return;
  const href=safeLink(anchor.href);
  if(!href)return;
  // 画像検索・Pinterest・写真の掲載元など、外部のhttp(s)リンクのみ。
  // クリック操作に同期して開く（setTimeoutや非同期処理を挟まない）。
  event.preventDefault();
  event.stopPropagation();
  let popup=null;
  try{popup=window.open('','_blank','popup=yes,width=1180,height=820,resizable=yes,scrollbars=yes,location=yes');}catch(error){popup=null;}
  if(!popup){toast('別ウィンドウがブロックされました。このカードのポップアップを許可して再度クリックしてください。');return;}
  try{popup.opener=null;popup.location.replace(href);popup.focus();}
  catch(error){try{popup.location.href=href;}catch(ignore){}toast('リンクの表示を確認できません。ブラウザのポップアップ設定を確認してください。');}
},true);
function hsl(hex){const n=parseInt(hex.slice(1),16),r=(n>>16&255)/255,g=(n>>8&255)/255,b=(n&255)/255,hi=Math.max(r,g,b),lo=Math.min(r,g,b),d=hi-lo,l=(hi+lo)/2,sat=d===0?0:d/(1-Math.abs(2*l-1));let hue=0;if(d!==0){if(hi===r)hue=60*(((g-b)/d)%6);else if(hi===g)hue=60*((b-r)/d+2);else hue=60*((r-g)/d+4);if(hue<0)hue+=360;}return [sat<.08?1:0,hue,l,sat];}
function hueOrder(){return CARDS.map((c,i)=>({i,k:hsl(effectiveColor(c).hex)})).sort((a,b)=>a.k[0]-b.k[0]||a.k[1]-b.k[1]||a.k[2]-b.k[2]||a.k[3]-b.k[3]||a.i-b.i).map(a=>a.i);}
const state={order:hueOrder(),shuffled:false,origin:'all',cat:'all',query:'',index:0,flipped:false,mode:'study',page:0};
function matches(c,cat=state.cat){const r=research(c);return (state.origin==='all'||c.origin===state.origin)&&(cat==='all'||effectiveColor(c).category===cat)&&(!state.query||(c.name+' '+(r.jp||'')+' '+(r.en||'')).toLowerCase().includes(state.query));}
function filtered(){return state.order.filter(i=>matches(CARDS[i]));}
function selected(){const v=filtered();state.index=Math.max(0,Math.min(state.index,Math.max(v.length-1,0)));return v.length?{v,i:v[state.index],c:CARDS[v[state.index]]}:null;}
function swapOrder(shuffled){const v=hueOrder();if(shuffled)for(let i=v.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[v[i],v[j]]=[v[j],v[i]];}state.order=v;state.shuffled=shuffled;state.index=0;state.flipped=false;state.page=0;render();}
function change(delta){
  const doc=document.scrollingElement||document.documentElement;
  const keepY=window.scrollY||doc.scrollTop||0,keepX=window.scrollX||doc.scrollLeft||0;
  const v=filtered();
  state.index=Math.max(0,Math.min(v.length-1,state.index+delta));
  state.flipped=false;
  render();
  requestAnimationFrame(()=>requestAnimationFrame(()=>{
    const tail=document.getElementById('cardNavScrollTail');
    if(tail){
      tail.style.height='0px';
      const nowY=window.scrollY||doc.scrollTop||0;
      const realEnd=tail.getBoundingClientRect().top+nowY;
      const viewport=window.innerHeight||document.documentElement.clientHeight||0;
      tail.style.height=Math.max(0,Math.ceil(keepY+viewport-realEnd))+'px';
    }
    try{window.scrollTo({top:keepY,left:keepX,behavior:'instant'});}
    catch(_){window.scrollTo(keepX,keepY);}
  }));
}
function flip(){state.flipped=!state.flipped;selectedPhotoKey=null;render();}
function changeMode(mode){state.mode=mode;render();}
function jump(idx){let v=filtered();if(!v.includes(idx)){state.origin='all';state.cat='all';state.query='';$('search').value='';v=filtered();}state.index=v.indexOf(idx);state.flipped=false;state.mode='study';render();}
function mark(v){const it=selected();if(!it)return;progress[it.c.name+'|'+it.c.hex]=v;try{localStorage.setItem('colors1000_verified_progress',JSON.stringify(progress));}catch{toast('学習記録は進捗JSONで保存してください。');}change(1);}
function sourcePhoto(index,role){const r=research(CARDS[index]);let p=role==='origin'?r.photo:r.usage_examples?.[role];if(!p)return null;if(role==='origin'){const cache=ORIGIN_PHOTO_RENDER_CACHE[p.page];if(cache)p={...p,url:cache.url,changes:cache.changes};if(r.origin_status!=='confirmed'&&!['name_image','name_imagery','image'].includes(p.role)&&!r.name_image&&!p.name_image)return null;}else if(p.status!=='verified')return null;return p;}
function slotPhoto(index,role){const key=`${CARD_IDS[index]}:${role}`;if(own(manualEdits,key)){const edit=manualEdits[key];if(!edit.deleted)return {...edit,url:edit.data_url,manual:true};return null;}const mapped=PRIVATE_PHOTO_MAP[key];if(mapped)return {url:mapped,manifest_asset:true};const p=sourcePhoto(index,role);return p&&!p.display_suppressed_duplicate?p:null;}
function photoCredit(p){if(p.manual)return p.label?`<p>${escapeHtml(p.label)}</p>`:'';const attribution=USAGE_PHOTO_ATTRIBUTIONS[p.page];const lines=[externalLink(p.page,'写真の出典 ↗'),p.author?`撮影・著作：${escapeHtml(String(p.author).replace(/（[^（）]*未確認[^（）]*）/g,''))}`:'',attribution?`指定の帰属表示：${escapeHtml(attribution)}`:'',externalLink(p.license_url,p.license||'ライセンス'),p.changes?escapeHtml(p.changes):''];return lines.filter(Boolean).join('<br>');}
function searchTerms(c,role){const r=research(c),base=c.origin==='jp'?c.name:(r.en||c.name);const suffix=c.origin==='jp'?{origin:'',interior:'インテリア',fashion:'ファッション',product:'プロダクト',palette:'配色 カラーパレット'}[role]:{origin:'',interior:'interior',fashion:'fashion',product:'product',palette:'color palette color scheme'}[role];return [base,suffix].filter(Boolean).join(' ');}
function photoSlot(index,role){const c=CARDS[index],key=`${CARD_IDS[index]}:${role}`,p=slotPhoto(index,role),src=p&&safeImage(p.url),query=encodeURIComponent(searchTerms(c,role));return `<section class="photo-slot" data-photo-slot="${key}"><div class="usage-frame photo-frame" tabindex="0" role="button" aria-label="${escapeHtml(ROLE_LABELS[role])}の画像貼り付け先" data-paste-target="${key}">${src?`<img data-color-private-src="${escapeHtml(src)}" alt="${escapeHtml(p.label||ROLE_LABELS[role])}" loading="lazy" referrerpolicy="no-referrer">`:'<div class="usage-placeholder"><span>＋</span></div>'}</div><h3>${ROLE_LABELS[role]}</h3><div class="photo-search">${externalLink('https://www.google.com/search?tbm=isch&q='+query,'Google画像')}${externalLink('https://www.pinterest.com/search/pins/?q='+query,'Pinterest画像')}</div><div class="photo-actions"><button type="button" data-photo-file="${key}">画像を選ぶ</button><button type="button" data-photo-paste="${key}">貼り付け</button><button type="button" data-photo-remove="${key}" ${p?'':'disabled'}>削除</button>${own(manualEdits,key)?`<button type="button" class="restore" data-photo-restore="${key}">元の写真に戻す</button>`:''}<input type="file" accept="image/png,image/jpeg,image/webp,image/gif" data-photo-input="${key}" hidden></div>${p?`<div class="photo-credit">${p.label&&!p.manual?`<p>${escapeHtml(p.label)}</p>`:''}${photoCredit(p)}</div>`:''}</section>`;}
function renderBack(c,index){const back=$('back');$('cardArea').classList.toggle('flipped',state.flipped);if(!state.flipped){back.className='back hidden';back.innerHTML='';return;}const r=research(c),colour=effectiveColor(c),description=r.origin_display_text||'';back.className='back';back.innerHTML=`<div class="card-title-row"><div class="card-color-chip" style="background:${colour.hex}" aria-hidden="true"></div><div class="card-title-copy"><h2>${escapeHtml(c.name)}</h2><p class="color-appearance">${escapeHtml(r.jp&&r.jp!==c.name?r.jp+' · ':'')}<code>${colour.hex}</code> · <code>RGB ${colour.rgb.join(', ')}</code></p>${displayColorReferenceMarkup(c)}</div></div><div class="origin-layout"><section class="origin-copy"><h3>名前の由来</h3>${description?`<p>${escapeHtml(description)}</p>`:''}</section>${photoSlot(index,'origin')}</div><div class="usage-grid">${photoSlot(index,'interior')}${photoSlot(index,'fashion')}${photoSlot(index,'product')}</div><p class="paste-hint">写真欄をクリックして Ctrl＋V で貼り付けられます。</p>`;bindPhotoActions();back.querySelectorAll('img').forEach(img=>{img.addEventListener('error',()=>{const message=document.createElement('div');message.className='usage-placeholder';message.textContent='画像を読み込めませんでした';img.replaceWith(message);});});}
function renderCategories(){const cats=[['all','すべて','#889db9'],...CATEGORIES.map((c,i)=>[c,c,['#b72a39','#eb752c','#dbb53b','#64aa58','#2bafaf','#326fcb','#8360b8','#e590ac','#9a6c43','#aab1bb'][i]])];$('cats').innerHTML=cats.map(([key,name,color])=>`<button class="category ${state.cat===key?'active':''}" data-cat="${escapeHtml(key)}"><span class="dot" style="background:${color}"></span>${escapeHtml(name)}<span class="count">${CARDS.filter(c=>matches(c,key)).length}</span></button>`).join('');$('cats').querySelectorAll('[data-cat]').forEach(btn=>btn.onclick=()=>{state.cat=btn.dataset.cat;state.index=0;state.page=0;state.flipped=false;render();});}
function renderPalette(it,v){$('palette').innerHTML=v.map(i=>`<button class="mini ${it&&it.i===i?'active':''}" aria-label="色見本 ${i+1}" data-index="${i}" style="background:${effectiveColor(CARDS[i]).hex}"></button>`).join('');$('palette').querySelectorAll('[data-index]').forEach(btn=>btn.onclick=()=>jump(Number(btn.dataset.index)));}
function renderList(v){const size=80,pages=Math.max(1,Math.ceil(v.length/size));state.page=Math.max(0,Math.min(pages-1,state.page));$('tiles').innerHTML=v.slice(state.page*size,state.page*size+size).map(i=>`<button class="tile" data-index="${i}"><div class="tileColor" style="background:${effectiveColor(CARDS[i]).hex}"></div><div class="tileName">${escapeHtml(CARDS[i].name)}</div></button>`).join('')||'該当する色がありません';$('tiles').querySelectorAll('[data-index]').forEach(b=>b.onclick=()=>jump(Number(b.dataset.index)));$('pageCounter').textContent=`${state.page+1} / ${pages} ページ`;$('pagePrev').disabled=state.page===0;$('pageNext').disabled=state.page===pages-1;}
function render(){const v=filtered(),it=selected();renderCategories();$('total').textContent=`現在の対象：${v.length}色`;$('origin').value=state.origin;$('modeStudy').classList.toggle('active',state.mode==='study');$('modeList').classList.toggle('active',state.mode==='list');$('study').classList.toggle('hide',state.mode!=='study');$('listing').classList.toggle('show',state.mode==='list');$('orderState').textContent=state.shuffled?'ランダム順':'色相順（近い色を並べる）';if(state.mode==='list'){renderList(v);return;}if(!it){$('counter').textContent='0 / 0';$('group').textContent='該当なし';$('cardArea').classList.remove('flipped');$('swatch').style.background='#ffffff';$('back').innerHTML='';$('back').className='back hidden';$('prev').disabled=$('next').disabled=true;renderPalette(null,v);return;}$('counter').textContent=`${state.index+1} / ${v.length}`;$('group').textContent=`${effectiveColor(it.c).category} ・ ${it.c.origin==='jp'?'日本':'海外'}`;$('swatch').style.background=effectiveColor(it.c).hex;$('prev').disabled=state.index===0;$('next').disabled=state.index===v.length-1;renderBack(it.c,it.i);renderPalette(it,v);const stats=Object.values(progress);$('progress').textContent=`覚えた ${stats.filter(x=>x==='known').length}色 ／ 復習 ${stats.filter(x=>x==='missed').length}色`;}
function openImageDb(){return new Promise((resolve,reject)=>{if(!window.indexedDB)return reject(new Error('画像の端末保存が利用できません。進捗JSONを保存してください。'));const req=indexedDB.open('colors1000_photo_edits_v1',1);req.onupgradeneeded=()=>req.result.createObjectStore('state');req.onerror=()=>reject(req.error);req.onsuccess=()=>resolve(req.result);});}
function dbRead(){return new Promise((resolve,reject)=>{const tx=imageDb.transaction('state','readonly'),req=tx.objectStore('state').get('manual_photo_edits');req.onsuccess=()=>resolve(req.result||{});req.onerror=()=>reject(req.error);});}
async function persistEdits(){await readyImages;if(!imageDb)throw new Error('端末保存が利用できません。進捗JSONを保存してください。');return new Promise((resolve,reject)=>{const tx=imageDb.transaction('state','readwrite');tx.objectStore('state').put(manualEdits,'manual_photo_edits');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);});}
function normalizeEdits(input){const out={};if(!input||typeof input!=='object')return out;for(const [key,value] of Object.entries(input)){if(!VALID_SLOT_KEYS.has(key)||!value||typeof value!=='object')continue;if(value.deleted===true){out[key]={deleted:true,updated_at:String(value.updated_at||'')};continue;}const data_url=value.data_url||value.url;if(/^data:image\/(?:png|jpeg|webp|gif);base64,/i.test(String(data_url))&&safeImage(data_url)){out[key]={data_url,sha256:/^[a-f0-9]{64}$/i.test(value.sha256||'')?value.sha256:null,pixel_sha256:/^[a-f0-9]{64}$/i.test(value.pixel_sha256||'')?value.pixel_sha256:null,label:String(value.label||''),updated_at:String(value.updated_at||'')};}}return out;}
async function digestBytes(bytes){if(window.crypto?.subtle){const h=await crypto.subtle.digest('SHA-256',bytes);return [...new Uint8Array(h)].map(v=>v.toString(16).padStart(2,'0')).join('');}return sha256Fallback(new Uint8Array(bytes));}
function sha256Fallback(bytes){const K=[0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2];const l=bytes.length,padded=new Uint8Array(Math.ceil((l+9)/64)*64);padded.set(bytes);padded[l]=128;const view=new DataView(padded.buffer);view.setUint32(padded.length-8,Math.floor(l/0x20000000));view.setUint32(padded.length-4,l<<3);const H=[0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19],w=new Uint32Array(64),rr=(x,n)=>(x>>>n)|(x<<(32-n));for(let off=0;off<padded.length;off+=64){for(let i=0;i<16;i++)w[i]=view.getUint32(off+i*4);for(let i=16;i<64;i++){const x=w[i-15],y=w[i-2];w[i]=(w[i-16]+(rr(x,7)^rr(x,18)^(x>>>3))+w[i-7]+(rr(y,17)^rr(y,19)^(y>>>10)))>>>0;}let [a,b,c,d,e,f,g,h]=H;for(let i=0;i<64;i++){const t1=(h+(rr(e,6)^rr(e,11)^rr(e,25))+((e&f)^(~e&g))+K[i]+w[i])>>>0,t2=((rr(a,2)^rr(a,13)^rr(a,22))+((a&b)^(a&c)^(b&c)))>>>0;h=g;g=f;f=e;e=(d+t1)>>>0;d=c;c=b;b=a;a=(t1+t2)>>>0;}[a,b,c,d,e,f,g,h].forEach((v,i)=>H[i]=(H[i]+v)>>>0);}return H.map(v=>v.toString(16).padStart(8,'0')).join('');}
function bytesOfDataUrl(url){const text=atob(url.split(',')[1]),bytes=new Uint8Array(text.length);for(let i=0;i<text.length;i++)bytes[i]=text.charCodeAt(i);return bytes;}
function knownHash(p){return p?.sha256||p?.embedded_file_sha256||String(p?.url||'').match(/assets\/([a-f0-9]{64})\./)?.[1]||null;}
function duplicateSlot(sha,key,pixelHash){for(let i=0;i<CARDS.length;i++)for(const role of ROLES){const other=`${CARD_IDS[i]}:${role}`;if(other===key)continue;const p=slotPhoto(i,role);if(!p)continue;if(knownHash(p)===sha||(pixelHash&&p.pixel_sha256===pixelHash))return other;}return null;}
async function pixelDigest(blob){const bitmap=await createImageBitmap(blob);try{if(bitmap.width*bitmap.height>30000000)throw new Error('画像が大きすぎます。3000万画素以下の画像を選んでください。');const canvas=document.createElement('canvas');canvas.width=bitmap.width;canvas.height=bitmap.height;const ctx=canvas.getContext('2d',{willReadFrequently:true});ctx.drawImage(bitmap,0,0);const pixels=ctx.getImageData(0,0,canvas.width,canvas.height).data;const hash=await digestBytes(pixels);return `${hash}`;}finally{bitmap.close();}}
async function setImage(key,file){await readyImages;if(!VALID_SLOT_KEYS.has(key))throw new Error('写真欄を選んでください。');if(!['image/png','image/jpeg','image/webp','image/gif'].includes(file.type))throw new Error('PNG・JPEG・WebP・GIF画像を選んでください。');if(file.size>15*1024*1024)throw new Error('15MB以下の画像を選んでください。');const bytes=await file.arrayBuffer(),sha256=await digestBytes(bytes),pixel_sha256=await pixelDigest(file);if(duplicateSlot(sha256,key,pixel_sha256))throw new Error('この写真は別の欄で使用されています。別の写真を選んでください。');const data_url=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(reader.error);reader.readAsDataURL(file);});if(duplicateSlot(sha256,key,pixel_sha256))throw new Error('この写真は別の欄で使用されています。別の写真を選んでください。');manualEdits[key]={data_url,sha256,pixel_sha256,label:'',updated_at:new Date().toISOString()};render();try{await persistEdits();toast('画像を保存しました。進捗JSONでも持ち出せます。');}catch(e){toast(e.message||'端末保存できません。進捗JSONを保存してください。');}}
async function changeEdit(key,restore){await readyImages;const previous=manualEdits[key];if(restore){delete manualEdits[key];const [id,role]=key.split(':'),index=CARD_IDS.indexOf(id),p=slotPhoto(index,role),hash=knownHash(p);if(hash&&duplicateSlot(hash,key,p?.pixel_sha256)){manualEdits[key]=previous;toast('この写真は別の欄で使用されています。別の写真を選んでください。');return;}}else manualEdits[key]={deleted:true,updated_at:new Date().toISOString()};render();try{await persistEdits();}catch(e){toast(e.message);}}
function selectPasteTarget(key){selectedPhotoKey=key;const frame=document.querySelector(`[data-paste-target="${key}"]`);if(frame&&document.activeElement!==frame)frame.focus({preventScroll:true});document.querySelectorAll('[data-paste-target]').forEach(el=>el.classList.toggle('selected',el.dataset.pasteTarget===key));}
function bindPhotoActions(){const back=$('back');back.querySelectorAll('[data-paste-target]').forEach(el=>{el.onclick=()=>selectPasteTarget(el.dataset.pasteTarget);el.onfocus=()=>selectPasteTarget(el.dataset.pasteTarget);el.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();selectPasteTarget(el.dataset.pasteTarget);}if(e.code==='Space')e.preventDefault();};});back.querySelectorAll('[data-photo-file]').forEach(btn=>btn.onclick=()=>{selectPasteTarget(btn.dataset.photoFile);back.querySelector(`[data-photo-input="${btn.dataset.photoFile}"]`).click();});back.querySelectorAll('[data-photo-input]').forEach(input=>input.onchange=()=>{const file=input.files[0];if(file)setImage(input.dataset.photoInput,file).catch(e=>toast(e.message));});back.querySelectorAll('[data-photo-paste]').forEach(btn=>btn.onclick=async()=>{selectPasteTarget(btn.dataset.photoPaste);try{if(!navigator.clipboard?.read)throw new Error('写真欄をクリックして Ctrl＋V で貼り付けてください。');const entries=await navigator.clipboard.read();for(const entry of entries){const type=entry.types.find(t=>['image/png','image/jpeg','image/webp','image/gif'].includes(t));if(type){await setImage(btn.dataset.photoPaste,await entry.getType(type));return;}}toast('クリップボードに画像がありません。');}catch(e){toast(e.message||'写真欄をクリックして Ctrl＋V で貼り付けてください。');}});back.querySelectorAll('[data-photo-remove]').forEach(btn=>btn.onclick=()=>changeEdit(btn.dataset.photoRemove,false));back.querySelectorAll('[data-photo-restore]').forEach(btn=>btn.onclick=()=>changeEdit(btn.dataset.photoRestore,true));}
document.addEventListener('paste',e=>{const target=e.target.closest?.('[data-paste-target]');if(!target||!state.flipped)return;const key=target.dataset.pasteTarget;const file=[...(e.clipboardData?.items||[])].find(i=>i.kind==='file'&&i.type.startsWith('image/'))?.getAsFile();if(file){e.preventDefault();setImage(key,file).catch(err=>toast(err.message));}});
function validateStudyProgress(input){const keys=new Set(CARDS.map(c=>c.name+'|'+c.hex)),out={};if(input&&typeof input==='object')for(const [key,value] of Object.entries(input))if(keys.has(key)&&['known','missed'].includes(value))out[key]=value;return out;}
async function importData(data){if(!data||!Array.isArray(data.cards)||data.cards.length!==CARDS.length)throw new Error('1000色の進捗JSONを選んでください。');const map=new Map();for(const c of data.cards){if(!c||typeof c.id!=='string'||map.has(c.id))throw new Error('色IDに重複があります。');map.set(c.id,c);}for(let i=0;i<CARDS.length;i++){const c=map.get(CARD_IDS[i]),base=CARDS[i];if(!c||c.name!==base.name||String(c.hex).toUpperCase()!==base.hex)throw new Error('色ID・色名・色値が一致しません。対応する進捗JSONを選んでください。');if(!c.research||typeof c.research!=='object')throw new Error('色のデータを読み込めません。');}if(!data.review43||!data.cards.every(c=>own(c.research,'origin_display_text')))throw new Error('review43以降の進捗JSONを選んでください。現在の調査結果はそのまま保持しました。');await readyImages;const edits=normalizeEdits(data.manual_photo_edits||{});for(const [key,edit]of Object.entries(edits)){if(!edit.deleted){edit.sha256=await digestBytes(bytesOfDataUrl(edit.data_url));}}const oldEdits=manualEdits,oldResearch={...RESEARCH_DATA},oldOriginProgress=makeProgressExport(false),displayMerge=mergeDisplaySpecifications(data);manualEdits=edits;for(let i=0;i<CARDS.length;i++){const name=CARDS[i].name;RESEARCH_DATA[name]=mergeOriginResearch(RESEARCH_DATA[name],map.get(CARD_IDS[i]).research,CARD_IDS[i]);}for(const [key,edit]of Object.entries(edits)){if(!edit.deleted&&duplicateSlot(edit.sha256,key,edit.pixel_sha256)){manualEdits=oldEdits;Object.assign(RESEARCH_DATA,oldResearch);throw new Error('読み込む写真に他の欄との重複があります。');}}importedProgress=mergeOriginProgressMetadata(oldOriginProgress,data);for(const key of Object.keys(DISPLAY_COLOR_SPECIFICATIONS))delete DISPLAY_COLOR_SPECIFICATIONS[key];Object.assign(DISPLAY_COLOR_SPECIFICATIONS,displayMerge.specifications);DISPLAY_COLOR_POLICY=displayMerge.policy;DISPLAY_COLOR_REFERENCE_QUEUE=displayMerge.queue;DISPLAY_COLOR_IMPORT_CONFLICTS=displayMerge.conflicts;DISPLAY_REFERENCE_REVISION=displayMerge.referenceRevision;DISPLAY_REFERENCE_CONFLICTS=displayMerge.referenceConflicts;if(!state.shuffled)state.order=hueOrder();progress=validateStudyProgress(data.study_progress||{});try{localStorage.setItem('colors1000_verified_progress',JSON.stringify(progress));}catch{}state.flipped=false;render();try{await persistEdits();toast('写真・学習記録を読み込みました。');}catch{toast('読み込みました。進捗JSONを保存して編集を保管してください。');}}
$('shuffle').onclick=()=>swapOrder(true);$('reset').onclick=()=>swapOrder(false);$('modeStudy').onclick=()=>changeMode('study');$('modeList').onclick=()=>changeMode('list');$('prev').onclick=()=>change(-1);$('next').onclick=()=>change(1);$('flip').onclick=flip;$('swatch').onclick=flip;$('known').onclick=()=>mark('known');$('missed').onclick=()=>mark('missed');$('origin').onchange=e=>{state.origin=e.target.value;state.index=0;state.flipped=false;state.page=0;render();};$('search').oninput=e=>{state.query=e.target.value.trim().toLowerCase();state.index=0;state.flipped=false;state.page=0;render();};$('back').onclick=e=>{if(!e.target.closest('a,button,input,summary,details,[data-photo-slot]'))flip();};$('back').onkeydown=e=>{if(e.target===$('back')&&e.key==='Enter')flip();};$('pagePrev').onclick=()=>{state.page--;renderList(filtered());};$('pageNext').onclick=()=>{state.page++;renderList(filtered());};document.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName)||e.target.closest?.('[data-photo-slot]')||e.ctrlKey||e.metaKey||e.altKey)return;if(e.key==='ArrowLeft')change(-1);else if(e.key==='ArrowRight')change(1);else if(e.code==='Space'){e.preventDefault();flip();}else if(e.key.toLowerCase()==='s')swapOrder(true);else if(e.key.toLowerCase()==='r')swapOrder(false);});
$('saveEdits').onclick=async()=>{try{await persistEdits();toast('画像編集を保存しました。引き継ぎには進捗JSONも保存してください。');}catch(e){toast(e.message||'端末保存できません。進捗JSONを保存してください。');}};
$('exportResearch').onclick=async()=>{await readyImages;const data=makeProgressExport(),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.download='colors1000_progress_light_review47.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);};
$('importResearch').onclick=()=>$('importFile').click();$('importFile').onchange=async()=>{const file=$('importFile').files[0];$('importFile').value='';if(!file)return;try{await importData(JSON.parse(await file.text()));}catch(e){toast(e.message||'進捗JSONを読み込めませんでした。');}};
const readyImages=(async()=>{const embedded=makeProgressExport(false);manualEdits=normalizeEdits(embedded.manual_photo_edits||{});if(embedded.study_progress)progress={...validateStudyProgress(embedded.study_progress),...progress};try{imageDb=await openImageDb();const saved=normalizeEdits(await dbRead());for(const [key,value]of Object.entries(saved)){if(!manualEdits[key]||String(value.updated_at)>=String(manualEdits[key].updated_at))manualEdits[key]=value;}}catch{}render();})();
